  private readonly api = inject(RatesApi);

  /** The sheet's rates; a grade with no rate is not listed. */
  readonly rates = input.required<RateView[]>();
  /** The sheet's today, on which each grade's rate in force is shown. */
  readonly today = input.required<string>();
  /** A rate set through the form. */
  readonly saved = output<RateView>();

  protected readonly grades = GRADES;
  protected readonly noRate = NO_RATE;
  protected readonly grade = signal<Grade>('A');
  protected readonly pct = signal('');
  /** The from-date typed (yyyy-mm-dd); empty means from the beginning of time. */
  protected readonly from = signal('');
  /** The to-date typed (yyyy-mm-dd); empty means no end. */
  protected readonly to = signal('');
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  /** Every rate by grade, each grade's from the start, then by from-date. */
  protected readonly listed = computed(() =>
    [...this.rates()].sort((a, b) =>
      a.grade !== b.grade ? a.grade.localeCompare(b.grade) : (a.from ?? '').localeCompare(b.from ?? ''),
    ),
  );

  protected currentOf(grade: Grade): string | null {
    return rateOn(this.rates(), grade, this.today());
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected gradeOf(event: Event): Grade {
    return (event.target as HTMLSelectElement).value as Grade;
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const pct = this.pct().trim();
    if (!PERCENT.test(pct)) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = this.from().trim();
    if (from !== '' && !FROM_DATE.test(from)) {
      this.error.set('Type a from-date as yyyy-mm-dd, or leave it empty for from the start.');
      return;
    }
    const to = this.to().trim();
    if (to !== '' && !FROM_DATE.test(to)) {
      this.error.set('Type a to-date as yyyy-mm-dd, or leave it empty for no end.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      // The refused dates are cleared, so they are not carried into the next rate set.
      this.from.set('');
      this.to.set('');
      this.error.set(`A to-date cannot be before the from-date; ${from} and ${to} were cleared.`);
      return;
    }
    this.busy = true;
    try {
      this.saved.emit(await this.api.set(sheet, this.grade(), { pct, from: from || null, to: to || null }));
      this.pct.set('');
      this.from.set('');
      this.to.set('');
    } catch {
      this.error.set(`The rate for grade ${this.grade()} could not be set.`);
    } finally {
      this.busy = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView, LateTerms, cents, isCorrection, lateBoundaries, money } from './claims';
import { valueOn } from './session';
import { Grade } from './people';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, e.g. "12.50". */
  pct: string;
  /** The date (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) the rate applies on; null when it has no end. */
  to: string | null;
}

/**
 * A rate as set through the form; a null from-date applies from the beginning of time, a null
 * to-date has no end.
 */
export interface RateForm {
  pct: string;
  from: string | null;
  to: string | null;
}

/** A from-date as a rate takes it: yyyy-mm-dd. */
export const FROM_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): of its rates with no from-date or one on or
 * before the date, the one with the latest; null when the date is before every rate of the grade, or
 * after that one's to-date.
 */
export function rateOn(rates: RateView[], grade: Grade, date: string): string | null {
  let best: RateView | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  if (best === null || (best.to !== null && best.to < date)) return null;
  return best.pct;
}

/** Whether two rates are for the same grade and from-date, so one replaces the other. */
export function sameSlot(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from;
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,3}(\.\d{1,2})?$/;

/** Shown in place of a due when the grade has no rate. */
export const NO_RATE = 'n/a';

/**
 * What is due on an amount in whole cents at a rate (a two-decimal percent): the amount times the
 * rate divided by 100, rounded half to even (or half up) to whole cents (a negative amount rounds as
 * its opposite does). Worked in integers so it is exact.
 */
export function dueCents(amountCents: number, pct: string, times = 1, halfUp = false): number {
  if (amountCents < 0) return -dueCents(-amountCents, pct, times, halfUp);
  const [whole, frac = ''] = pct.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  const exact = BigInt(amountCents) * basisPoints * BigInt(times);
  const quotient = exact / 10000n;
  const remainder = exact % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return Number(up ? quotient + 1n : quotient);
}

/** What is due on an amount in whole cents at a rate, shown with two decimals; n/a with no rate in force. */
export function due(amountCents: number, pct: string | null): string {
  return pct === null ? NO_RATE : money(dueCents(amountCents, pct));
}

/**
 * A claim's due in whole cents: the due fixed when it was settled (frozen as it was settled), or else
 * the greater of the floor (in whole cents) and its figure with the late charge on top. Its figure is
 * the rate figure its person's last statement bound it to (unless it is PENDING), or else its amount
 * at the rate the grade has in force on the claim's date; the late charge is, for every full 30 days
 * the claim is overdue, the late percent in force on that boundary date (its due-by plus 30, 60, 90
 * ... days) of the figure plus the charges of the boundaries before it (compounding), each rounded
 * like the claim, added up. The floor is applied last; the one
 * given is the one in force on the claim's date. Live figures round half up when `halfUp` (see
 * roundsHalfUp), else half to even. The charge and floor are never bound by a statement. A correction
 * has no floor and no late charge. Null when there is no figure.
 */
export function claimDueCents(
  claim: ClaimView,
  rates: RateView[],
  grade: Grade,
  floorCents: number,
  late: LateTerms,
  halfUp = false,
